public class Main {
    static List<Integer>[] adj;
    static List<Integer>[] reverseAdj;
    static int[] mark;
    static int[] ans;
    static int[] state;
    static int[] stack;

    static void dfs1(int start) {
        int top = 0;
        stack[top++] = start;
        mark[start] = 1;

        while (top > 0) {
            int x = stack[--top];
            ans[x]++;

            List<Integer> edges = adj[x];
            if (edges == null) continue;

            for (int u : edges) {
                if (mark[u] == 0) {
                    mark[u] = 1;
                    stack[top++] = u;
                }
            }
        }
    }

    static void dfs2(int start) {
        int top = 0;
        stack[top++] = start;
        mark[start] = 1;

        while (top > 0) {
            int x = stack[--top];
            ans[x]++;

            if (state[x] == 1) continue;

            List<Integer> edges = reverseAdj[x];
            if (edges == null) continue;

            for (int u : edges) {
                if (mark[u] == 0) {
                    mark[u] = 1;
                    stack[top++] = u;
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner in = new FastScanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();

        state = new int[n];
        mark = new int[n];
        ans = new int[n];
        stack = new int[n];

        @SuppressWarnings("unchecked")
        List<Integer>[] forward = (List<Integer>[]) new List<?>[n];
        @SuppressWarnings("unchecked")
        List<Integer>[] backward = (List<Integer>[]) new List<?>[n];
        adj = forward;
        reverseAdj = backward;

        for (int i = 0; i < n; i++) {
            state[i] = in.nextInt();
        }

        for (int i = 0; i < m; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;

            if (adj[u] == null) adj[u] = new ArrayList<>();
            if (reverseAdj[v] == null) reverseAdj[v] = new ArrayList<>();

            adj[u].add(v);
            reverseAdj[v].add(u);
        }

        for (int i = 0; i < n; i++) {
            if (mark[i] == 0 && state[i] == 1) {
                dfs1(i);
            }
        }

        Arrays.fill(mark, 0);

        for (int i = 0; i < n; i++) {
            if (mark[i] == 0 && state[i] == 2) {
                dfs2(i);
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++) {
            output.append(ans[i] == 2 ? 1 : 0).append('\n');
        }
        System.out.print(output);
    }

